import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react'
import { Link } from '@tanstack/react-router'
import { GarfexLogoNegative } from '../../shared/design-system/GarfexLogoNegative'
import { useGlobalCommandShortcut } from '../../shared/keyboard/useGlobalCommandShortcut'
import { CommandEntry } from './CommandEntry'

export function AppShell({ children }: { children: ReactNode }) {
  const [commandOpen, setCommandOpen] = useState(false)
  const openerRef = useRef<HTMLElement | null>(null)
  const wasOpenRef = useRef(false)

  const openCommand = useCallback((opener: HTMLElement | null) => {
    openerRef.current = opener?.isConnected ? opener : null
    setCommandOpen(true)
  }, [])
  const closeCommand = useCallback(() => setCommandOpen(false), [])

  useGlobalCommandShortcut(openCommand, commandOpen)

  useEffect(() => {
    if (commandOpen) {
      wasOpenRef.current = true
      return
    }
    if (!wasOpenRef.current) return
    const opener = openerRef.current
    if (opener?.isConnected && !opener.hasAttribute('disabled')) opener.focus()
    openerRef.current = null
    wasOpenRef.current = false
  }, [commandOpen])

  return (
    <div className="app-shell">
      <aside className="app-rail">
        <div className="brand-lockup">
          <GarfexLogoNegative />
        </div>
        <nav aria-label="Navegación principal" className="primary-navigation">
          <Link
            to="/bandeja"
            activeProps={{ className: 'navigation-link is-active' }}
            className="navigation-link"
          >
            Bandeja
          </Link>
        </nav>
      </aside>
      <div className="app-workspace">
        <header className="topbar">
          <CommandEntry
            isOpen={commandOpen}
            onOpen={openCommand}
            onClose={closeCommand}
          />
        </header>
        <main className="workspace-main">{children}</main>
      </div>
    </div>
  )
}

import { expect, test } from '@playwright/test'
import AxeBuilder from '@axe-core/playwright'

test.describe('Bandeja workstation 1440×980', () => {
  test('exposes the honest runtime shell and route', async ({ page }) => {
    await page.goto('/')
    await expect(page).toHaveURL(/\/bandeja$/)
    await expect(page.getByRole('heading', { name: 'Bandeja' })).toBeVisible()
    await expect(
      page.getByRole('navigation', { name: 'Navegación principal' }),
    ).toBeVisible()
    await expect(page.getByRole('img', { name: 'GARFEX' })).toBeVisible()
    await expect(page.locator('table')).toHaveCount(0)
    await expect(page.locator('[aria-busy="true"]')).toHaveCount(0)
    await expect(page.locator('[aria-live]')).toHaveCount(0)
    await expect(
      page.getByText(/23|Administrador|Sincronizado|sin pendientes/i),
    ).toHaveCount(0)
  })

  test('keeps native tab order and restores focus around commands', async ({
    page,
  }) => {
    await page.goto('/bandeja')
    const trigger = page.getByRole('button', {
      name: /Buscar o ejecutar comando/,
    })
    await trigger.focus()
    await page.keyboard.press('Enter')
    await expect(
      page.getByRole('dialog', { name: 'Entrada de comandos' }),
    ).toBeVisible()
    await expect(page.getByRole('textbox', { name: 'Comando' })).toBeFocused()
    await page.keyboard.press('Escape')
    await expect(page.getByRole('dialog')).toHaveCount(0)
    await expect(trigger).toBeFocused()

    await page.keyboard.press('ControlOrMeta+KeyK')
    await expect(page.getByRole('textbox', { name: 'Comando' })).toBeFocused()
    await page.keyboard.press('Escape')
    await expect(trigger).toBeFocused()
  })

  test('passes applicable axe checks without adding responsive variants', async ({
    page,
  }) => {
    await page.goto('/bandeja')
    const results = await new AxeBuilder({ page }).analyze()
    expect(results.violations).toEqual([])
    expect(
      await page.evaluate(() => ({
        width: window.innerWidth,
        height: window.innerHeight,
      })),
    ).toEqual({ width: 1440, height: 980 })
  })
})
